def split_row(line: str):
    fields = []
    current_field = ""
    in_quotes = False
    i = 0
    while i < len(line):
        char = line[i]

        if char == '"':
            if in_quotes and i + 1 < len(line) and line[i+1] == '"':
                # Escaped quote
                current_field += '"'
                i += 1 # Skip the next quote
            else:
                in_quotes = not in_quotes
        elif char == ',' and not in_quotes:
            fields.append(current_field)
            current_field = ""
        else:
            current_field += char
        i += 1
    fields.append(current_field)
    return fields

